</div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.querySelectorAll('[data-confirm]').forEach(x=>x.addEventListener('click',e=>{if(!confirm(x.dataset.confirm))e.preventDefault()}));const kode=document.querySelector('input[name="kode"]');if(kode){kode.readOnly=true;kode.placeholder='Otomatis dibuat saat disimpan';if(!kode.value)kode.value='Otomatis dibuat';}const reader=document.querySelector('#reader');if(reader){const fallback=document.createElement('div');fallback.className='alert alert-info text-start mt-3';fallback.innerHTML='<b>Alternatif scan dengan foto</b><br><small>Jika kamera live diblokir sertifikat atau izin browser, ambil foto QR lalu sistem akan membacanya.</small><label class="btn btn-outline-primary w-100 mt-2">Ambil Foto QR<input id="qr-photo-input" type="file" accept="image/*" capture="environment" hidden></label><div id="photo-qr-reader" class="small mt-2"></div>';reader.insertAdjacentElement('afterend',fallback);document.querySelector('#qr-photo-input').addEventListener('change',async ev=>{const file=ev.target.files[0],out=document.querySelector('#photo-qr-reader');if(!file)return;out.textContent='Membaca QR Code...';try{if(typeof Html5Qrcode==='undefined')throw new Error('Library scanner belum termuat');const scanner=new Html5Qrcode('photo-qr-reader');const decoded=await scanner.scanFile(file,true);if(typeof ok==='function')ok(decoded);else location.href=decoded;}catch(err){out.innerHTML='<span class="text-danger">QR tidak dapat dibaca. Pastikan foto fokus dan library scanner dapat diakses.</span>';}});}const menuToggle=document.querySelector('#mobile-menu-toggle'),sidebar=document.querySelector('#sidebar');if(menuToggle&&sidebar){let menuBackdrop;const closeMenu=()=>{sidebar.classList.remove('mobile-open','show','showing','hiding');sidebar.removeAttribute('style');menuToggle.setAttribute('aria-expanded','false');if(window.bootstrap){const instance=bootstrap.Offcanvas.getInstance(sidebar);if(instance)instance.hide();}if(menuBackdrop){menuBackdrop.remove();menuBackdrop=null;}};menuToggle.addEventListener('click',()=>{if(sidebar.classList.contains('mobile-open'))closeMenu();else{sidebar.classList.add('mobile-open');menuToggle.setAttribute('aria-expanded','true');menuBackdrop=document.createElement('div');menuBackdrop.className='mobile-menu-backdrop';menuBackdrop.addEventListener('click',closeMenu);document.body.appendChild(menuBackdrop);}});sidebar.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));sidebar.querySelector('.btn-close')?.addEventListener('click',event=>{event.preventDefault();closeMenu();});}</script></body></html>
